//! Same card, generated by the official route: leptos_router static routes.

use card::{Creature, CreatureCard, Index};
use leptos::prelude::*;
use leptos_router::{
    components::{FlatRoutes, Route, Router},
    hooks::use_params_map,
    path,
    static_routes::StaticRoute,
    SsrMode,
};

const IDS: [&str; 3] = ["aboleth", "aasimar", "ankheg"];

pub fn shell(options: LeptosOptions) -> impl IntoView {
    view! {
        <!DOCTYPE html>
        <html lang="pt-BR">
            <head>
                <meta charset="utf-8"/>
                <meta name="viewport" content="width=device-width, initial-scale=1"/>
                <style>"body{font-family:system-ui,sans-serif;max-width:40rem;margin:0 auto;padding:1rem}img{display:block;width:100%;height:auto}"</style>
                <HydrationScripts options/>
            </head>
            <body>
                <App/>
            </body>
        </html>
    }
}

#[component]
pub fn App() -> impl IntoView {
    view! {
        <Router>
            <FlatRoutes fallback=|| "Página não encontrada.">
                <Route path=path!("/") view=IndexPage ssr=SsrMode::Static(StaticRoute::new())/>
                <Route
                    path=path!("/:id/")
                    view=CreaturePage
                    ssr=SsrMode::Static(
                        StaticRoute::new().prerender_params(|| async move {
                            [("id".into(), IDS.iter().map(|s| s.to_string()).collect())]
                                .into_iter()
                                .collect()
                        }),
                    )
                />
            </FlatRoutes>
        </Router>
    }
}

#[component]
fn IndexPage() -> impl IntoView {
    let list = Resource::new_blocking(|| (), |_| list_creatures());
    view! {
        <Suspense fallback=|| "Carregando...">
            {move || Suspend::new(async move {
                list.await.ok().map(|entries| view! { <Index entries/> })
            })}
        </Suspense>
    }
}

#[component]
fn CreaturePage() -> impl IntoView {
    let params = use_params_map();
    let id = move || params.read().get("id").unwrap_or_default();
    let creature = Resource::new_blocking(id, get_creature);
    view! {
        <Suspense fallback=|| "Carregando...">
            {move || Suspend::new(async move {
                creature.await.ok().map(|creature| view! { <CreatureCard creature/> })
            })}
        </Suspense>
    }
}

#[cfg(feature = "ssr")]
fn read_creature(id: &str) -> Result<Creature, ServerFnError> {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../dados")
        .join(format!("{id}.json"));
    let json = std::fs::read_to_string(path).map_err(|e| ServerFnError::new(e.to_string()))?;
    serde_json::from_str(&json).map_err(|e| ServerFnError::new(e.to_string()))
}

#[server]
pub async fn get_creature(id: String) -> Result<Creature, ServerFnError> {
    read_creature(&id)
}

#[server]
pub async fn list_creatures() -> Result<Vec<(String, String)>, ServerFnError> {
    IDS.iter()
        .map(|id| read_creature(id).map(|c| (c.id, c.name)))
        .collect()
}

#[cfg(feature = "hydrate")]
#[wasm_bindgen::prelude::wasm_bindgen]
pub fn hydrate() {
    leptos::mount::hydrate_body(App);
}
